import React from 'react';
import { useParams, Link } from 'react-router-dom';
import { Container, Card, Button, Badge } from 'react-bootstrap';
import { dishes } from './mockData';

const DishDetail = () => {
  const { dishId } = useParams();
  const dish = dishes.find((d) => d.id === parseInt(dishId, 10));

  if (!dish) {
    return (
      <Container className="text-center mt-5">
        <h3>Dish not found!</h3>
        <Link to="/dishes" className="btn btn-primary mt-3">Back to Menu</Link>
      </Container>
    );
  }

  return (
    <Container className="mt-5" style={{ maxWidth: '600px' }}>
      <Card className="shadow">
        <Card.Img 
          variant="top" 
          src={dish.image} 
          alt={dish.name} 
          style={{ height: '350px', objectFit: 'cover' }}
        />
        <Card.Body>
          <div className="d-flex justify-content-between align-items-center mb-2">
            <Card.Title className="fw-bold fs-3 mb-0">{dish.name}</Card.Title>
            {dish.label && <Badge bg="danger">{dish.label}</Badge>}
          </div>
          <h5 className="text-success mb-3">${dish.price}</h5>
          <Card.Text>{dish.description}</Card.Text>
          <p className="text-muted text-uppercase small">Category: {dish.category}</p>
          <Button as={Link} to="/dishes" variant="outline-secondary">
            Back to Menu
          </Button>
        </Card.Body>
      </Card>
    </Container>
  );
};

export default DishDetail;
